$('#clear-files').onclick=()=>{files=[];invalidateDraft({discardTranslation:true});resetPreview();renderFiles();$('#file').value='';void window.clearStudioDraft();toast('Dateien und Entwurf aus dieser Sitzung entfernt.')};
function outputTitle(){const source=resolvedSourceLanguage(),from={Arabisch:'dem Arabischen',Englisch:'dem Englischen',Deutsch:'dem Deutschen',Französisch:'dem Französischen',Spanisch:'dem Spanischen',Italienisch:'dem Italienischen',Türkisch:'dem Türkischen'}[source],target=draftTargetLanguage||$('#target-language').value,to={Deutsch:'ins Deutsche',Englisch:'ins Englische',Arabisch:'ins Arabische',Französisch:'ins Französische',Spanisch:'ins Spanische',Italienisch:'ins Italienische',Türkisch:'ins Türkische'}[target];return `Beglaubigte Übersetzung aus ${from||source} ${to||'nach '+target}`;}
function exportText(){const text=$('#translation').value.trim();if(!window.ensureExportSourceLanguage())return null;if(!text){toast('Bitte zuerst eine Übersetzung eingeben.');return null}if(/zu prüfen|prüfhinweis|\b(?:TODO|TBD)\b/i.test(text)){toast('Bitte offene Angaben vor dem Export klären.');return null}return `${outputTitle()}\n\n${text}`}
function exported(){document.querySelectorAll('.step').forEach(s=>s.classList.add('active'));toast('Übersetzung exportiert.')}
$('#download').onclick=()=>{const text=exportText();if(!text)return;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='foliquo-uebersetzung.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);exported()};$('#print').onclick=()=>{const text=exportText();if(!text)return;const page=document.createElement('article');page.className='print-document';const h=document.createElement('h1');h.textContent=outputTitle();const content=document.createElement('div');content.className='print-translation';content.textContent=$('#translation').value.trim();page.append(h,content);$('#print-area').replaceChildren(page);window.print();exported()};window.addEventListener('beforeunload',()=>urls.forEach(URL.revokeObjectURL));

let providerContextState=null;window.syncTranslateContext=function(event){const status=document.querySelector('#provider-status'),target=document.querySelector('#provider-context-status');if(event?.detail?.providerName)providerContextState=event.detail;if(providerContextState)window.translateProviderContextState=providerContextState;if(status&&target){const state=providerContextState;if(state){const parts=[['provider',state.providerName],['model',state.modelName],['state',state.status]],nodes=[];for(const [kind,text] of parts){if(!text)continue;const value=document.createElement('span');value.className='provider-context-'+kind;if(kind!=='state')value.dataset.noTranslate='';value.textContent=text;nodes.push(value);}target.replaceChildren(...nodes);target.dataset.ready=String(state.ready);target.dataset.provider=state.providerId||'';target.dataset.model=state.modelId||'';}else{target.textContent=status.textContent;target.dataset.ready=status.dataset.ready||'false';}}const type=document.querySelector('#document-type-context-value');if(type)type.textContent=detectedDocument?.documentType||uiText('Wird automatisch erkannt');}
document.querySelector('#provider-context-open')?.addEventListener('click',event=>window.openAISettings?.(event.currentTarget));window.addEventListener('translateocr-ai-state',syncTranslateContext);window.addEventListener('translateocr-ready',syncTranslateContext);window.addEventListener('translateocr-locale',syncTranslateContext);
